import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Html5QrcodeScanner } from 'html5-qrcode';
import { api } from '../services/api';
import toast, { Toaster } from 'react-hot-toast';

const QRScannerPage: React.FC = () => {
    const [scanResult, setScanResult] = useState<string | null>(null);
    const [isVerifying, setIsVerifying] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        const scanner = new Html5QrcodeScanner(
            "reader",
            {
                fps: 10,
                qrbox: { width: 250, height: 250 },
                rememberLastUsedCamera: true,
                aspectRatio: 1.0
            },
      /* verbose= */ false
        );

        scanner.render(onScanSuccess, onScanFailure);

        function onScanSuccess(decodedText: string) {
        console.log("Scanned value:", decodedText);

        let bookingId = decodedText;

        try {
            const parsed = JSON.parse(decodedText);
            bookingId = parsed.sessionId; // ✅ IMPORTANT
        } catch (err) {
            console.error("QR is not valid JSON");
        }

        if (!bookingId) {
            toast.error("Invalid QR Code");
            return;
        }

        setScanResult(bookingId);
        handleVerify(bookingId, scanner);
        }


        function onScanFailure(error: any) {
            // Handle scan failure - usually just noise or not found
            // console.warn(`Code scan error = ${error}`);
        }

        return () => {
            scanner.clear().catch(error => {
                console.error("Failed to clear html5QrcodeScanner. ", error);
            });
        };
    }, []);

    const handleVerify = async (bookingId: string, scanner: any) => {
        if (isVerifying) return;

        setIsVerifying(true);
        toast.loading('Verifying QR Code...', { id: 'verify' });

        try {
            const response = await api.verifyQR(bookingId);
            if (response.success) {
                toast.success(response.message || 'Access Granted!', { id: 'verify', duration: 4000 });
                // Optionally stay or navigate after delay
                setTimeout(() => navigate('/dashboard'), 3000);
            } else {
                toast.error(response.message || 'Invalid or Expired QR', { id: 'verify', duration: 4000 });
                // Reset to allow another scan
                setScanResult(null);
                setIsVerifying(false);
            }
        } catch (error) {
            toast.error('Server error during verification', { id: 'verify' });
            setIsVerifying(false);
            setScanResult(null);
        }
    };

    return (
        <div style={styles.container}>
            <Toaster position="top-center" />
            <div style={styles.header}>
                <button onClick={() => navigate('/dashboard')} style={styles.backBtn}>
                    ← Back to Dashboard
                </button>
                <h1 style={styles.title}>QR Code Scanner</h1>
                <p style={styles.subtitle}>Scan user booking QR to verify entry</p>
            </div>

            <div style={styles.scannerWrapper}>
                <div id="reader" style={styles.reader}></div>
                {scanResult && (
                    <div style={styles.resultBox}>
                        <p style={styles.resultText}>Detected ID: {scanResult}</p>
                        {isVerifying && <p style={styles.loadingText}>Authenticating...</p>}
                    </div>
                )}
            </div>

            <div style={styles.instructions}>
                <h3 style={styles.instTitle}>Instructions:</h3>
                <ul style={styles.instList}>
                    <li>Allow camera access when prompted</li>
                    <li>Center the QR code in the box</li>
                    <li>Keep the camera steady</li>
                    <li>The system will automatically verify once scanned</li>
                </ul>
            </div>
        </div>
    );
};

const styles = {
    container: {
        minHeight: '100vh',
        background: '#0a192f',
        color: '#e6f1ff',
        padding: '40px 20px',
        display: 'flex',
        flexDirection: 'column' as const,
        alignItems: 'center',
    },
    header: {
        textAlign: 'center' as const,
        marginBottom: '30px',
        maxWidth: '600px',
        width: '100%',
    },
    backBtn: {
        background: 'transparent',
        border: 'none',
        color: '#64ffda',
        cursor: 'pointer',
        fontSize: '16px',
        marginBottom: '20px',
        display: 'block',
    },
    title: {
        fontSize: '32px',
        color: '#64ffda',
        margin: '0 0 10px 0',
    },
    subtitle: {
        color: '#8892b0',
        fontSize: '16px',
    },
    scannerWrapper: {
        width: '100%',
        maxWidth: '500px',
        background: '#112240',
        borderRadius: '16px',
        padding: '20px',
        boxShadow: '0 10px 30px rgba(0,0,0,0.5)',
        border: '1px solid rgba(100, 255, 218, 0.1)',
    },
    reader: {
        width: '100%',
        borderRadius: '8px',
        overflow: 'hidden',
        border: 'none',
    },
    resultBox: {
        marginTop: '20px',
        padding: '15px',
        background: 'rgba(100, 255, 218, 0.1)',
        borderRadius: '8px',
        textAlign: 'center' as const,
    },
    resultText: {
        margin: 0,
        fontSize: '14px',
        wordBreak: 'break-all' as const,
    },
    loadingText: {
        margin: '10px 0 0 0',
        color: '#64ffda',
        fontWeight: 'bold' as const,
    },
    instructions: {
        marginTop: '30px',
        maxWidth: '500px',
        width: '100%',
        padding: '20px',
        background: 'rgba(255,255,255,0.03)',
        borderRadius: '12px',
    },
    instTitle: {
        fontSize: '18px',
        color: '#64ffda',
        marginBottom: '10px',
    },
    instList: {
        color: '#8892b0',
        fontSize: '14px',
        lineHeight: '1.6',
        paddingLeft: '20px',
    }
};

export default QRScannerPage;
